-- bakery: generated by schema-starter from bakery.json
BEGIN;
CREATE SCHEMA bakery;
COMMENT ON SCHEMA bakery IS 'A neighborhood bakery that takes orders for pickup.';
SET LOCAL search_path TO bakery;

CREATE TABLE customer (
    customer_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    full_name   text NOT NULL CHECK (full_name <> ''),
    email       text NOT NULL UNIQUE CHECK (email = lower(email) AND email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
    created_at  timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE customer IS 'Someone who orders from the bakery.';

CREATE TABLE product (
    product_id  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    title       text NOT NULL UNIQUE CHECK (title <> ''),
    category    text NOT NULL CHECK (category IN ('bread', 'pastry', 'cake')),
    price       numeric(12,2) NOT NULL CHECK (price >= 0),
    stock_count integer NOT NULL CHECK (stock_count >= 0),
    created_at  timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE product IS 'Something the bakery sells.';

CREATE TABLE customer_order (
    customer_order_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    pickup_at         timestamptz NOT NULL,
    status            text NOT NULL CHECK (status IN ('placed', 'baking', 'ready', 'picked_up', 'canceled')),
    customer_id       bigint NOT NULL REFERENCES customer (customer_id) ON DELETE RESTRICT,
    created_at        timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE customer_order IS 'One order, picked up at one time.';
CREATE INDEX customer_order_customer_id_idx ON customer_order (customer_id);

CREATE TABLE review (
    review_id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    rating      smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment     text,
    product_id  bigint NOT NULL REFERENCES product (product_id) ON DELETE CASCADE,
    customer_id bigint REFERENCES customer (customer_id) ON DELETE SET NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (product_id, customer_id)
);
COMMENT ON TABLE review IS 'A customer''s rating of a product: one per customer per product.';
CREATE INDEX review_customer_id_idx ON review (customer_id);

CREATE TABLE customer_phone (
    customer_id bigint NOT NULL REFERENCES customer (customer_id) ON DELETE CASCADE,
    phone       text NOT NULL CHECK (phone <> ''),
    PRIMARY KEY (customer_id, phone)
);
COMMENT ON TABLE customer_phone IS 'Each phone of a customer, one per row.';

CREATE TABLE product_allergen (
    product_id bigint NOT NULL REFERENCES product (product_id) ON DELETE CASCADE,
    allergen   text NOT NULL CHECK (allergen IN ('gluten', 'dairy', 'egg', 'nuts')),
    PRIMARY KEY (product_id, allergen)
);
COMMENT ON TABLE product_allergen IS 'Each allergen of a product, one per row.';

CREATE TABLE order_line (
    customer_order_id bigint NOT NULL REFERENCES customer_order (customer_order_id) ON DELETE CASCADE,
    product_id        bigint NOT NULL REFERENCES product (product_id) ON DELETE RESTRICT,
    quantity          integer NOT NULL CHECK (quantity BETWEEN 1 AND 100),
    unit_price        numeric(12,2) NOT NULL CHECK (unit_price >= 0),
    PRIMARY KEY (customer_order_id, product_id)
);
COMMENT ON TABLE order_line IS 'One product on one order.';
COMMENT ON COLUMN order_line.unit_price IS 'The price when the order was placed: product.price can change later.';
CREATE INDEX order_line_product_id_idx ON order_line (product_id);

COMMIT;
